mapper.select:
SELECT p.* FROM fund_financing_repay_actual_lib p
INNER JOIN (SELECT main_id AS financing_id, MAX(version) AS version FROM common_version t1
WHERE t1.module = 'FUND_FINANCING' AND version_type = 1
GROUP BY main_id) m ON p.financing_id = m.financing_id AND p.version = m.version
WHERE 1 = 1

    AND p.financing_id IN
    
        #{item}
    


    AND p.repay_date >= #{startDate}


    AND p.repay_date <= #{endDate}

ORDER BY p.repay_date DESC

SELECT p.* FROM fund_financing_repay_actual_lib p, fund_financing_base_info b WHERE b.financing_status IN ( 'CARRY_INTEREST' ) AND p.financing_id = b.id AND p.version = (select version from common_version c where c.version_type = 1 AND c.module = 'FUND_FINANCING' AND c.main_id = p.financing_id ORDER BY version DESC LIMIT 1)
AND b.time_limit_type = #{dto.timeLimitType}
AND p.repay_date between #{dto.fromTime} and #{dto.toTime} ORDER BY p.repay_date
